import { useRouteError } from 'react-router-dom';
import MainNavigation from '../components/MainNavigation';

import PageContent from '../components/PageContent';

function ErrorPage() {
  const error = useRouteError();

  let title = 'An error occurred!';
  let message = 'Something went wrong!';

  // Helper function to extract message from error data
  const getErrorMessage = (data) => {
    if (!data) return null;
    // When using json() from react-router-dom, data is already parsed
    if (typeof data === 'object' && data.message) {
      return data.message;
    }
    // Fallback for string data (in case Response was used directly)
    if (typeof data === 'string') {
      try {
        const parsed = JSON.parse(data);
        return parsed.message || data;
      } catch {
        return data;
      }
    }
    return null;
  };

  // Handle Response/json errors (thrown from loaders)
  if (error.status) {
    if (error.status === 404) {
      title = 'Not found!';
      message = getErrorMessage(error.data) || 'Could not find resource or page.';
    } else if (error.status === 500) {
      message = getErrorMessage(error.data) || 'Something went wrong!';
    } else {
      message = getErrorMessage(error.data) || error.message || 'Something went wrong!';
    }
  } else {
    // Handle other types of errors (e.g., navigation errors, network errors)
    message = error.message || 'Something went wrong!';
  }

  return (
    <>
      <MainNavigation />
      <PageContent title={title}>
        <p>{message}</p>
      </PageContent>
    </>
  );
}

export default ErrorPage;
